using CertDesk.Common; using CertDesk.Models; using CertDesk.Services;
namespace CertDesk.Forms;
public partial class CertificateEditForm:Form { public Certificate Certificate{get;} ComboBox emp=new(){Width=300,DropDownStyle=ComboBoxStyle.DropDownList}, auth=new(){Width=300,DropDownStyle=ComboBoxStyle.DropDownList}, tok=new(){Width=300,DropDownStyle=ComboBoxStyle.DropDownList}, type=new(){Width=120,DropDownStyle=ComboBoxStyle.DropDownList}; TextBox sn=new(){Width=300}, purpose=new(){Width=300}; DateTimePicker issued=new(), vf=new(), vt=new(); public CertificateEditForm(Certificate? c=null){Certificate=c??new Certificate(); InitializeComponent(); Build(); LoadLists(); if(c!=null) LoadC();} void Build(){ int y=15; void row(string l,Control c){Controls.Add(new Label{Text=l,Left=20,Top=y+3,Width=150}); c.Left=180;c.Top=y;Controls.Add(c);y+=38;} row("Владелец",emp); row("УЦ",auth); row("Токен",tok); row("Серийный номер",sn); row("Тип подписи",type); row("Дата выдачи",issued); row("Действует с",vf); row("Действует до",vt); row("Назначение",purpose); var ok=new Button{Text="Сохранить",Left=180,Top=y+10}; var cancel=new Button{Text="Отмена",Left=300,Top=y+10,DialogResult=DialogResult.Cancel}; UiTheme.ApplyButtonStyle(ok); Controls.AddRange(new Control[]{ok,cancel}); ok.Click+=Save;} void LoadLists(){ foreach(var e in EmployeeService.GetActive()) emp.Items.Add(new ComboBoxItem{Id=e.Id,Text=e.FullName}); foreach(var a in AuthorityService.GetActive()) auth.Items.Add(new ComboBoxItem{Id=a.Id,Text=a.Name}); tok.Items.Add(new ComboBoxItem{Id=null,Text="Без токена"}); foreach(var t in TokenService.GetAll()) tok.Items.Add(new ComboBoxItem{Id=t.Id,Text=t.InventoryNumber}); type.Items.AddRange(new object[]{"SES","NES","QES"}); if(emp.Items.Count>0) emp.SelectedIndex=0; if(auth.Items.Count>0) auth.SelectedIndex=0; tok.SelectedIndex=0; type.SelectedIndex=2;} void LoadC(){ Select(emp,Certificate.EmployeeId); Select(auth,Certificate.AuthorityId); Select(tok,Certificate.TokenId); sn.Text=Certificate.SerialNumber; type.SelectedItem=Certificate.SignatureType; issued.Value=Certificate.IssuedAt; vf.Value=Certificate.ValidFrom; vt.Value=Certificate.ValidTo; purpose.Text=Certificate.Purpose;} void Select(ComboBox c,int? id){ foreach(ComboBoxItem i in c.Items) if(i.Id==id){c.SelectedItem=i;break;}} void Save(object? _,EventArgs __){ if(emp.SelectedItem==null||auth.SelectedItem==null||string.IsNullOrWhiteSpace(sn.Text)){MessageHelper.Error("Заполните владельца, УЦ и серийный номер");return;} if(vt.Value.Date<vf.Value.Date||issued.Value.Date>vt.Value.Date){MessageHelper.Error("Проверьте даты сертификата");return;} Certificate.EmployeeId=((ComboBoxItem)emp.SelectedItem).Id!.Value; Certificate.AuthorityId=((ComboBoxItem)auth.SelectedItem).Id!.Value; Certificate.TokenId=((ComboBoxItem)tok.SelectedItem).Id; Certificate.SerialNumber=sn.Text.Trim(); Certificate.SignatureType=type.Text; Certificate.IssuedAt=issued.Value; Certificate.ValidFrom=vf.Value; Certificate.ValidTo=vt.Value; Certificate.Purpose=purpose.Text; DialogResult=DialogResult.OK;} }
